import java.io.BufferedInputStream
import java.io.PrintWriter

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val bufferSize = 1 shl 16
    private val buffer = ByteArray(bufferSize)
    private var len = 0
    private var ptr = 0

    private fun readByte(): Int {
        if (ptr >= len) {
            len = input.read(buffer)
            ptr = 0
            if (len <= 0) return -1
        }
        return buffer[ptr++].toInt()
    }

    fun nextLong(): Long {
        var c = readByte()
        while (c <= 32 && c >= 0) {
            c = readByte()
        }
        var sign = 1
        if (c == '-'.code) {
            sign = -1
            c = readByte()
        }
        var res = 0L
        while (c > 32) {
            res = res * 10 + (c - '0'.code)
            c = readByte()
        }
        return res * sign
    }
}

private fun solve(scanner: FastScanner, out: PrintWriter) {
    val l = scanner.nextLong()
    val r = scanner.nextLong()
    val x = scanner.nextLong()
    val y = scanner.nextLong()
    val k = scanner.nextLong()

    var j = x
    while (j <= y) {
        val t = j * k
        if (t > r) {
            break
        }
        if (t >= l && t <= r) {
            out.println("YES")
            return
        }
        j++
    }
    out.println("NO")
}

fun main() {
    val scanner = FastScanner()
    val out = PrintWriter(System.out)
    solve(scanner, out)
    out.flush()
}

